import{_ as n,a0 as o,w as p,s as d,ao as l,I as s,x as t,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇 | LCTT x X-CMD","titleTemplate":false,"description":"當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20190402 When Wi-Fi is mission-critical, a mixed-channel architecture is the best option","title":"當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇","tag":"202011","desc":""},"relativePath":"202011/20190402 When Wi-Fi is mission-critical, a mixed-channel architecture is the best option.md","filePath":"[post].md"}'),m={name:"202011/20190402 When Wi-Fi is mission-critical, a mixed-channel architecture is the best option.md"};function f(u,i,w,W,h,F){const e=o("Link");return p(),d("div",null,[i[21]||(i[21]=l('<h1 id="當-wi-fi-成為關鍵業務時-混合信道架構是最好的多信道選擇" tabindex="-1">當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇 <a class="header-anchor" href="#當-wi-fi-成為關鍵業務時-混合信道架構是最好的多信道選擇" aria-label="Permalink to “當 Wi-Fi 成為關鍵業務時，混合信道架構是最好的多信道選擇”">​</a></h1><blockquote><p>混合信道架構是最好的多信道選擇，但它並不總是最佳的選擇。當需要可靠的 Wi-Fi 時，單信道和混合 AP 提供了令人信服的替代方案。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/09/tablet_graph_wifi_analytics-100771638-large.jpg" alt="Getty Images"></p><p>我曾與許多實施數字項目的公司合作過，結果卻發現它們失敗了。正確的想法，健全地施行，現存的市場機遇。哪裏是薄弱的環節？是 Wi-Fi 網絡。</p><p>例如，一家大型醫院希望通過將遙測信息發送到移動設備，來提高臨牀醫生對患者警報的響應時間。如果沒有這個系統，護士瞭解病人警報的唯一途徑就是通過聲音警報。在所有嘈雜的背景音中，通常很難分辨噪音來自哪裏。問題是這家醫院中的 Wi-Fi 網絡已經很多年未升級了，這導致信息傳遞嚴重延遲（通常需要 4~5 分鐘）。過長的信息傳遞導致人們對該系統失去信心，因此許多臨牀醫生停止使用該系統，轉而使用手動警報。最終，人們認為這個項目是失敗的。</p><p>我曾在製造業、K-12 教育、娛樂和其他行業中見過類似的案例。企業競爭的基礎是客户體驗，而競爭的動力來自不斷擴展又無處不在的無線優勢。好的 Wi-Fi 並不意味着市場領導地位，但是劣質的 Wi-Fi 將會對客户和員工產生負面影響。而在當今競爭激烈的環境下，這是災難的根源。</p><h3 id="wi-fi-性能歷來不一致" tabindex="-1">Wi-Fi 性能歷來不一致 <a class="header-anchor" href="#wi-fi-性能歷來不一致" aria-label="Permalink to “Wi-Fi 性能歷來不一致”">​</a></h3><p>Wi-Fi 的問題在於它本身就很脆弱。我相信每個閲讀這篇文章的人都經歷過下載失敗、連接中斷、性能不一致以及連接公用熱點的漫長等待時間等缺陷。</p>',8)),s("p",null,[i[1]||(i[1]=t("想像一下，你在一個會議上，在一個主題演講之前，你可以隨意地發推特、發電子郵件、瀏覽網頁以及做其他事情。然後主講人上台，所有觀眾開始拍照，上傳並流傳信息——然後網絡崩潰了。我發現這不僅僅是一個例外，更是一種常態，強調了對",-1)),a(e,{href:"https://www.alliedtelesis.com/blog/no-compromise-wi-fi"},{default:r(()=>[...i[0]||(i[0]=[t("無損 Wi-Fi",-1)])]),_:1}),i[2]||(i[2]=t("的需求。",-1))]),i[22]||(i[22]=s("p",null,"對於網絡技術人員的問題是如何讓一個地方的 Wi-Fi 達到全部時間都保持不間斷。有人説只要加強現存的網絡可以做到，這也許可以，但在某些情況下，Wi-Fi 的類型可能並不合適。",-1)),s("p",null,[i[4]||(i[4]=t("最常見的 Wi-Fi 部署類型是多信道，也稱為微蜂窩，每個客户端通過無線信道連接到接入點（AP）。高質量的通話體驗基於兩點：良好的信號強度和最小的干擾。有幾個因素會導致干擾，例如接入點距離太近、佈局問題或者來自其他設備的干擾。為了最大程度地減少干擾，企業需要投入大量的時間和資金在",-1)),a(e,{href:"https://www.networkworld.com/article/3315269/wi-fi-site-survey-tips-how-to-avoid-interference-dead-spots.html"},{default:r(()=>[...i[3]||(i[3]=[t("現場調查中規劃最佳的信道地圖",-1)])]),_:1}),i[5]||(i[5]=t("，但即使這些做得很好，Wi-Fi 故障仍然可能發生。",-1))]),i[23]||(i[23]=l('<h2 id="多通道-wi-fi-並非總是最佳選擇" tabindex="-1">多通道 Wi-Fi 並非總是最佳選擇 <a class="header-anchor" href="#多通道-wi-fi-並非總是最佳選擇" aria-label="Permalink to “多通道 Wi-Fi 並非總是最佳選擇”">​</a></h2><p>對於許多鋪着地毯的辦公室來説，多通道 Wi-Fi 可能是可靠的，但在某些環境中，外部環境會影響性能。一個很好的例子是多租户建築，其中有多個 Wi-Fi 網絡在同一信道上傳輸並相互干擾。另一個例子是醫院，這裏有許多工作人員在多個接入點間流動。客户端將試圖連接到最佳接入點，導致客户端不斷斷開連接並重新連接，從而導致會話中斷。還有一些環境，例如學校、機場和會議設施，那裏存在大量的瞬態設備，而多通道則難以跟上。</p><h2 id="單通道-wi-fi-提供更好的可靠性但與此同時性能會受到影響" tabindex="-1">單通道 Wi-Fi 提供更好的可靠性但與此同時性能會受到影響 <a class="header-anchor" href="#單通道-wi-fi-提供更好的可靠性但與此同時性能會受到影響" aria-label="Permalink to “單通道 Wi-Fi 提供更好的可靠性但與此同時性能會受到影響”">​</a></h2><p>網絡管理器要做什麼？不一致的 Wi-Fi 只是一個既成事實嗎？多信道是一種標準，但它並非是為動態物理環境或那些需要可靠的連接環境而設計的。</p><p>幾年前提出了一項解決這些問題的替代架構。顧名思義，“單信道”Wi-Fi 在網絡中為所有接入點使用單一的無線頻道。可以把它想像成在一個信道上運行的單個 Wi-Fi 結構。這種架構中，接入點的位置無關緊要，因為它們都利用相同的通道，因此不會互相干擾。這有一個顯而易見的簡化優勢，比如，如果覆蓋率很低，那就沒有理由再做一次昂貴的現場調查。相反，只需在需要的地方佈置接入點就可以了。</p><p>單通道的缺點之一是總網絡吞吐量低於多通道，因為只能使用一個通道。在可靠性高於性能的環境中，這可能會很好，但許多組織希望二者兼而有之。</p><h2 id="混合接入點提供了兩全其美的優勢" tabindex="-1">混合接入點提供了兩全其美的優勢 <a class="header-anchor" href="#混合接入點提供了兩全其美的優勢" aria-label="Permalink to “混合接入點提供了兩全其美的優勢”">​</a></h2><p>單信道系統製造商最近進行了創新，將信道架構混合在一起，創造了一種“兩全其美”的部署，可提供多信道的吞吐量和單信道的可靠性。舉個例子，Allied Telesis 提供了混合接入點，可以同時在多信道和單信道模式下運行。這意味着可以分配一些 Web 客户端到多信道以獲得最大的吞吐量，而其他的 Web 客户端則可使用單信道來獲得無縫漫遊體驗。</p><p>這種混合的實際用例可能是物流設施，辦公室工作人員使用多通道，但叉車操作員在整個倉庫移動時使用單一通道持續連接。</p><p>Wi-Fi 曾是一個便利的網絡，但如今它或許是所有網絡中最關鍵的任務。傳統的多信道體系也許可以工作，但應該做一些盡職調查來看看它在重負下如何運轉。IT 領導者需要了解 Wi-Fi 對數字轉型計劃的重要性，並進行適當的測試，以確保它不是基礎設施鏈中的薄弱環節，併為當今環境選擇最佳技術。</p><hr>',11)),s("p",null,[i[7]||(i[7]=t("via: ",-1)),a(e,{href:"https://www.networkworld.com/article/3386376/when-wi-fi-is-mission-critical-a-mixed-channel-architecture-is-the-best-option.html"},{default:r(()=>[...i[6]||(i[6]=[t("https://www.networkworld.com/article/3386376/when-wi-fi-is-mission-critical-a-mixed-channel-architecture-is-the-best-option.html",-1)])]),_:1})]),s("p",null,[i[12]||(i[12]=t("作者：",-1)),a(e,{href:"https://www.networkworld.com/author/Zeus-Kerravala/"},{default:r(()=>[...i[8]||(i[8]=[t("Zeus Kerravala",-1)])]),_:1}),i[13]||(i[13]=t(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...i[9]||(i[9]=[t("lujun9972",-1)])]),_:1}),i[14]||(i[14]=t(" 譯者：",-1)),a(e,{href:"https://github.com/chenmu-kk"},{default:r(()=>[...i[10]||(i[10]=[t("chenmu-kk",-1)])]),_:1}),i[15]||(i[15]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:r(()=>[...i[11]||(i[11]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[18]||(i[18]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...i[16]||(i[16]=[t("LCTT",-1)])]),_:1}),i[19]||(i[19]=t(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:r(()=>[...i[17]||(i[17]=[t("Linux中國",-1)])]),_:1}),i[20]||(i[20]=t(" 榮譽推出",-1))])])}const C=n(m,[["render",f]]);export{x as __pageData,C as default};
